Fix the bug in sumAll. The inner var total shadows the outer total, so sum always returns 0.

function sumAll(values) {
  var total = 0;
  values.forEach(function(v) {
    var total = total + v;
  });
  return total;
}

Fix the closure bug in getCounters. Using var in the for loop makes all closures capture the same variable, so all return n+1 instead of 1..n.

function getCounters(n) {
  const fns = [];
  for (var i = 1; i <= n; i++) {
    fns.push(function() { return i; });
  }
  return fns.map(f => f());
}

Fix contains. Array.indexOf returns 0 (falsy) when item is at index 0, causing false negatives. Return a boolean.

function contains(arr, item) {
  return arr.indexOf(item);
}

